from itertools import combinations
found = False
for length in range(1, 20):
    for combo in combinations(range(1, length), 3):  # 5 marks: 0, a,b,c,length with 1<=a<b<c<length
        marks = [0] + list(combo) + [length]
        if is_golomb(marks):
            print(marks)
            found = True
            break
    if found:
        break
